b:if.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:         AI Khobor24
Version:      1.0
Type:         News Portal
-----------------------------------------------*/
/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#c8102e" value="#c8102e"/>
*/
:root{
  --brand:#c8102e; --brand-d:#9d0c24; --bg:#f4f5f7; --card:#ffffff; --text:#14171a;
  --muted:#6b7280; --line:#e5e7eb; --nav:#111827; --radius:10px;
  --shadow:0 1px 3px rgba(0,0,0,.06),0 6px 18px rgba(0,0,0,.05); --max:1220px;
  --font:'Inter','Noto Sans Bengali',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
}
:root[data-theme='dark']{--bg:#0d1117;--card:#161b22;--text:#e6edf3;--muted:#8b949e;--line:#262c36;--nav:#010409;--shadow:0 1px 3px rgba(0,0,0,.4)}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--text);font:400 16px/1.65 var(--font);-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
a:hover{color:var(--brand)}
img{max-width:100%;height:auto}
h1,h2,h3,h4{line-height:1.3;margin:0 0 .5em;font-weight:700}
#navbar-iframe,.Navbar,.widget-item-control,.quickedit{display:none!important}
.wrap{max-width:var(--max);margin:0 auto;padding:0 16px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
#progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--brand);z-index:999}

.topbar{background:var(--nav);color:#cbd5e1;font-size:13px}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;min-height:36px;gap:12px}
#theme-btn{background:none;border:1px solid #334155;color:#cbd5e1;border-radius:20px;padding:3px 12px;cursor:pointer;font:inherit;font-size:12px}

.site-head{background:var(--card);border-bottom:1px solid var(--line)}
.site-head .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-top:18px;padding-bottom:18px}
.logo{font-size:34px;font-weight:800;letter-spacing:-.5px;margin:0;line-height:1.1}
.logo a{color:var(--text)}
.logo a::first-letter{color:var(--brand)}
.logo img{max-height:64px;width:auto;display:block}
.head-ad{flex:1;display:flex;justify-content:flex-end;max-width:728px}
.head-ad .widget{margin:0}

.mainnav{background:var(--brand);position:sticky;top:0;z-index:100;box-shadow:0 2px 8px rgba(0,0,0,.15)}
.mainnav .wrap{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap}
.mainnav .menu-area{flex:1}
.mainnav .widget{margin:0}
.menu{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap}
.menu a{display:block;color:#fff;padding:13px 16px;font-weight:600;font-size:15px}
.menu a:hover{background:var(--brand-d);color:#fff}
.search-box{display:flex}
.search-box input{border:0;padding:8px 12px;border-radius:6px 0 0 6px;width:170px;font:inherit;font-size:14px;background:#fff;color:#111}
.search-box button{border:0;background:var(--nav);color:#fff;padding:0 14px;border-radius:0 6px 6px 0;cursor:pointer;font-size:14px}
#menu-btn{display:none;background:none;border:0;color:#fff;font-size:26px;padding:8px;cursor:pointer}

.ticker{background:var(--card);border-bottom:1px solid var(--line);overflow:hidden}
.ticker .wrap{display:flex;align-items:center;gap:14px;height:42px}
.ticker b{background:var(--brand);color:#fff;font-size:12px;padding:4px 10px;border-radius:4px;white-space:nowrap;text-transform:uppercase;letter-spacing:.5px}
.ticker .rail{overflow:hidden;flex:1;white-space:nowrap}
.ticker .track{display:inline-block;padding-left:100%;animation:tick 45s linear infinite}
.ticker .rail:hover .track{animation-play-state:paused}
.ticker .track a{margin-right:36px;font-size:14px;font-weight:500}
.ticker .track a::before{content:'\25CF';color:var(--brand);margin-right:8px;font-size:9px;vertical-align:middle}
@keyframes tick{to{transform:translateX(-100%)}}

.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:28px;margin:24px auto}
.widget{margin-bottom:24px}
.widget-title,.sec-title{font-size:17px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;margin:0 0 16px;padding-bottom:8px;border-bottom:2px solid var(--line);position:relative}
.widget-title::after,.sec-title::after{content:'';position:absolute;left:0;bottom:-2px;width:60px;height:2px;background:var(--brand)}
.sidebar .widget{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:var(--shadow)}
.sidebar ul,.sidebar ol{list-style:none;margin:0;padding:0}
.pop li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);align-items:center}
.pop li:last-child{border:0}
.pop img{width:72px;height:54px;object-fit:cover;border-radius:6px;flex:0 0 72px;display:block}
.pop a.pt{font-weight:600;font-size:14.5px;line-height:1.4}
.cats li{border-bottom:1px solid var(--line)}
.cats li:last-child{border:0}
.cats a{display:flex;justify-content:space-between;padding:10px 0;font-weight:500}
.cats span{color:var(--muted);font-size:13px}

#hero{display:grid;grid-template-columns:2fr 1fr 1fr;grid-template-rows:240px 240px;gap:10px;margin:22px 0}
#hero:empty{display:none}
#hero .ov:first-child{grid-row:span 2}
.ov{position:relative;border-radius:var(--radius);overflow:hidden;background:#222;min-height:150px}
.ov .thumb,.ov img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ov img{transition:transform .5s}
.ov:hover img{transform:scale(1.05)}
.ov .cb{position:absolute;left:0;right:0;bottom:0;padding:50px 16px 14px;background:linear-gradient(transparent,rgba(0,0,0,.85));color:#fff}
.ov h3{font-size:16px;margin:6px 0 4px}
.ov:first-child h3{font-size:26px}
.ov a:hover{color:#fff}
.ov time{font-size:12px;opacity:.8}
.tag{display:inline-block;background:var(--brand);color:#fff;font-size:11px;font-weight:700;padding:2px 9px;border-radius:3px;text-transform:uppercase;letter-spacing:.4px}
a.tag:hover{color:#fff;background:var(--brand-d)}

.block{background:var(--card);border-radius:var(--radius);padding:18px;margin-bottom:24px;box-shadow:var(--shadow)}
.bh{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid var(--line);margin-bottom:16px}
.bh h2{margin:0;font-size:17px;text-transform:uppercase;letter-spacing:.4px;padding-bottom:8px;border-bottom:2px solid var(--brand);margin-bottom:-2px}
.bh a{font-size:13px;color:var(--muted);font-weight:600}
.bg{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.lead .thumb{display:block;aspect-ratio:16/9;border-radius:8px;overflow:hidden;background:var(--line)}
.lead img{width:100%;height:100%;object-fit:cover;transition:transform .4s;display:block}
.lead:hover img{transform:scale(1.04)}
.lead h3{font-size:19px;margin:12px 0 4px}
.lead time,.mini time{font-size:12px;color:var(--muted)}
.minis{display:flex;flex-direction:column;gap:14px}
.mini{display:flex;gap:12px}
.mini .thumb{flex:0 0 96px;height:72px;border-radius:6px;overflow:hidden;background:var(--line)}
.mini img{width:100%;height:100%;object-fit:cover;display:block}
.mini h3{font-size:14.5px;margin:0 0 3px}
.noimg{display:block;width:100%;height:100%;background:linear-gradient(135deg,var(--line),var(--bg))}

.post-list{display:flex;flex-direction:column;gap:18px}
.item{display:flex;gap:18px;background:var(--card);padding:14px;border-radius:var(--radius);box-shadow:var(--shadow)}
.item .thumb{flex:0 0 260px;aspect-ratio:16/10;border-radius:8px;overflow:hidden;background:var(--line);display:block}
.item .thumb img{width:100%;height:100%;object-fit:cover;transition:transform .4s;display:block}
.item:hover .thumb img{transform:scale(1.05)}
.item h2{font-size:21px;margin:8px 0}
.item p{margin:0 0 8px;color:var(--muted);font-size:15px}
.meta{font-size:12.5px;color:var(--muted);display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.blog-pager{display:flex;justify-content:space-between;gap:10px;margin:24px 0}
.blog-pager a{display:inline-block;background:var(--brand);color:#fff;padding:10px 22px;border-radius:6px;font-weight:600}
.blog-pager a:hover{background:var(--brand-d);color:#fff}

.article{background:var(--card);padding:28px;border-radius:var(--radius);box-shadow:var(--shadow)}
.crumbs{font-size:13px;color:var(--muted);margin-bottom:14px}
.crumbs a{color:var(--muted)}
.article h1{font-size:32px;letter-spacing:-.4px;margin:10px 0 14px}
.article .meta{padding:12px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:20px}
.post-body{font-size:18px;line-height:1.85;overflow-wrap:break-word}
.post-body img{border-radius:8px;height:auto}
.post-body a{color:var(--brand)}
.post-body blockquote{border-left:4px solid var(--brand);margin:20px 0;padding:6px 18px;background:var(--bg);border-radius:0 8px 8px 0;font-style:italic}
.post-body table{max-width:100%;display:block;overflow-x:auto}
.post-body iframe{max-width:100%}
.labels a{display:inline-block;border:1px solid var(--line);padding:3px 12px;border-radius:20px;font-size:13px;margin:0 6px 6px 0}
.labels a:hover{border-color:var(--brand)}
.share{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}
.share a,.share button{border:0;cursor:pointer;color:#fff;font:600 13px var(--font);padding:9px 16px;border-radius:6px}
.share a:hover{color:#fff;opacity:.9}
.s-fb{background:#1877f2}.s-x{background:#111}.s-wa{background:#25d366}.s-tg{background:#229ed9}.s-cp{background:#6b7280}
#related{margin-top:28px}
.rel-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.rel-grid .lead h3{font-size:15px}
.comments{margin-top:28px}
.comments iframe,.comment-form iframe{width:100%;border:0}
#comment-holder ul,#comment-holder ol{list-style:none;padding-left:0}
#comment-holder .comment-block{margin:0 0 14px}
.err{text-align:center;padding:60px 20px;background:var(--card);border-radius:var(--radius)}
.err h1{font-size:72px;color:var(--brand);margin:0}

.site-foot{background:var(--nav);color:#94a3b8;margin-top:36px;padding:36px 0 18px}
.site-foot .cols{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}
.site-foot h3,.site-foot .widget-title{color:#fff;text-transform:uppercase;font-size:14px;letter-spacing:.5px;border:0;padding:0;margin-bottom:10px}
.site-foot .widget-title::after{display:none}
.site-foot .widget{margin:0}
.site-foot ul{list-style:none;margin:0;padding:0}
.site-foot a{color:#94a3b8;display:block;padding:4px 0}
.site-foot a:hover{color:#fff}
.copy{border-top:1px solid #1f2937;margin-top:24px;padding-top:16px;font-size:13px;text-align:center}
#totop{position:fixed;right:18px;bottom:18px;width:42px;height:42px;border:0;border-radius:50%;background:var(--brand);color:#fff;font-size:18px;cursor:pointer;opacity:0;pointer-events:none;transition:.3s;z-index:90}
#totop.show{opacity:1;pointer-events:auto}

@media(max-width:1000px){
  .layout{grid-template-columns:1fr}
  #hero{grid-template-columns:1fr 1fr;grid-template-rows:300px 180px 180px}
  #hero .ov:first-child{grid-column:span 2;grid-row:auto}
}
@media(max-width:760px){
  .head-ad{display:none}
  .site-head .wrap{justify-content:center;text-align:center}
  #menu-btn{display:block}
  .mainnav .menu-area{display:none;width:100%;order:3}
  .mainnav .menu-area.open{display:block}
  .menu{flex-direction:column}
  .search-box input{width:120px}
  .bg{grid-template-columns:1fr}
  .item{flex-direction:column}
  .item .thumb{flex:none;width:100%}
  .article{padding:18px}
  .article h1{font-size:25px}
  .post-body{font-size:17px}
  .rel-grid{grid-template-columns:1fr}
  .site-foot .cols{grid-template-columns:1fr}
  #hero{grid-template-columns:1fr;grid-template-rows:none}
  #hero .ov{height:210px}
  #hero .ov:first-child{grid-column:auto;height:260px}
  .ov:first-child h3{font-size:21px}
}
.widget ul,.widget ol{margin:0;padding-left:0;list-style:none}
.widget li{padding:6px 0}
.widget select,.widget input[type=text],.widget input[type=email],.widget textarea{width:100%;max-width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--card);color:var(--text);font:inherit}
.widget input[type=submit],.widget input[type=button],.widget button{background:var(--brand);color:#fff;border:0;border-radius:6px;padding:8px 16px;cursor:pointer;font:inherit;font-weight:600}
.BlogArchive ul.hierarchy{padding-left:14px}
.BlogArchive .zippy{color:var(--brand);cursor:pointer;margin-right:4px}
.Profile img{border-radius:50%}
.Image img,.FeaturedPost img{border-radius:8px}
.top-area .widget,.before-posts .widget,.after-posts .widget{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:var(--shadow)}
.site-foot .widget-content{color:#94a3b8}
.site-foot .widget a{display:inline}
.site-foot ul a{display:block}
.footer-bottom{text-align:center}
/* ---- Dark mode readability fixes ---- */
:root[data-theme='dark']{color-scheme:dark;--link:#ff6b81}
:root[data-theme='dark'] body,:root[data-theme='dark'] .article,:root[data-theme='dark'] .post-body,:root[data-theme='dark'] .widget,:root[data-theme='dark'] .block,:root[data-theme='dark'] .item{color:var(--text)}
:root[data-theme='dark'] .post-body a,:root[data-theme='dark'] .widget-content a{color:var(--link)}
:root[data-theme='dark'] .post-body :is(p,span,div,li,ul,ol,h1,h2,h3,h4,h5,h6,td,th,strong,b,em,i,u,font,blockquote,pre,code,small,label,figcaption,section,article){color:inherit!important}
:root[data-theme='dark'] .post-body :is(a,a *){color:var(--link)!important}
:root[data-theme='dark'] .post-body [style*='background'],:root[data-theme='dark'] .post-body [bgcolor]{background:transparent!important}
:root[data-theme='dark'] .post-body :is(table,td,th){border-color:var(--line)!important}
:root[data-theme='dark'] .post-body pre,:root[data-theme='dark'] .post-body code{background:var(--bg)!important;color:var(--text)!important}
:root[data-theme='dark'] .widget-content :is(p,span,div,li,font,td,th){color:inherit!important}
:root[data-theme='dark'] .comments,:root[data-theme='dark'] #comment-holder{color:var(--text)}
:root[data-theme='dark'] .comments iframe,:root[data-theme='dark'] .comment-form iframe{background:#fff;border-radius:8px}
:root[data-theme='dark'] .meta,:root[data-theme='dark'] .crumbs,:root[data-theme='dark'] .crumbs a,:root[data-theme='dark'] .lead time,:root[data-theme='dark'] .mini time{color:#a8b3c0}
:root[data-theme='dark'] .item p{color:#a8b3c0}
:root[data-theme='dark'] .labels a,:root[data-theme='dark'] .cats a,:root[data-theme='dark'] .pop a.pt{color:var(--text)}
:root[data-theme='dark'] .labels a:hover,:root[data-theme='dark'] .cats a:hover,:root[data-theme='dark'] .pop a.pt:hover,:root[data-theme='dark'] .item h2 a:hover,:root[data-theme='dark'] .lead h3 a:hover{color:var(--link)}
:root[data-theme='dark'] .site-foot,:root[data-theme='dark'] .site-foot p,:root[data-theme='dark'] .site-foot .widget-content,:root[data-theme='dark'] .copy{color:#a8b3c0}
:root[data-theme='dark'] .site-foot a{color:#a8b3c0}
:root[data-theme='dark'] .site-foot a:hover{color:#fff}
:root[data-theme='dark'] .widget select,:root[data-theme='dark'] .widget input[type=text],:root[data-theme='dark'] .widget input[type=email],:root[data-theme='dark'] .widget textarea{background:var(--bg);color:var(--text);border-color:var(--line)}
:root[data-theme='dark'] .search-box input{background:#1f2937;color:#e6edf3}
:root[data-theme='dark'] .search-box input::placeholder{color:#9aa4b2}
:root[data-theme='dark'] .err{color:var(--text)}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

b:if.b:template-skin:
html,body#layout #outer-wrapper,body#layout .row{width:auto;padding:0}
body#layout{position:relative;width:auto;max-width:100%;background-color:#f9f9f9;padding:60px 5px 0;margin:0}
body#layout:before{content:'AI Khobor24 - News Theme';position:absolute;top:0;left:5px;right:5px;height:60px;font-family:sans-serif;font-size:22px;color:#111;line-height:60px;text-align:center}
body#layout .wrap{max-width:100%}
body#layout div.section{margin:0 0 10px;padding:6px}
body#layout .layout{display:block}
body#layout .site-head .wrap,body#layout .mainnav .wrap,body#layout .topbar .wrap,body#layout .site-foot .cols{display:block;max-width:100%}
body#layout .head-ad{display:block;max-width:none;flex:none}
body#layout .mainnav{position:static}
body#layout .mainnav .menu-area{display:block!important;width:auto;order:0}
body#layout #menu-btn,body#layout .search-box,body#layout .topbar,body#layout .ticker,body#layout #hero,body#layout #totop,body#layout #progress{display:none!important}
body#layout .sidebar,body#layout main{width:auto;min-width:0}
body#layout .sidebar .widget{padding:0;box-shadow:none;background:none}
body#layout .site-foot{padding:0;background:none}
body#layout .block,body#layout .article{padding:0}

body.script:
//
(function(){
/* ---------- CONFIG: set these labels to match your Blogger labels ---------- */
var CFG={
  locale:'en-GB',      // use 'bn-BD' for Bengali dates
  tickerCount:8, heroCount:5, perSection:5,
  sections:[
    {label:'West Bengal',title:'West Bengal'},
    {label:'World',title:'World'},
    {label:'Politics',title:'Politics'},
    {label:'Technology',title:'Technology'},
    {label:'Sports',title:'Sports'},
    {label:'Entertainment',title:'Entertainment'}
  ]
};
var $=function(s,c){return (c||document).querySelector(s)};
var $$=function(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))};
var esc=function(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})};
var fmt=function(d){try{return new Date(d).toLocaleDateString(CFG.locale,{day:'numeric',month:'short',year:'numeric'})}catch(e){return ''}};
var B=document.body;
var isHome=B.classList.contains('is-home')&&location.pathname==='/'&&!/updated-max|[?&]q=/.test(location.search);
var isPost=B.classList.contains('is-post');

function resize(u,w){
  if(!u)return '';
  var h=Math.round(w*9/16);
  return u.replace(/\/(s\d+|w\d+-h\d+)(-[a-z0-9]+)*\//,'/w'+w+'-h'+h+'-c/').replace(/=(s|w)\d+(-[a-z0-9]+)*$/,'=w'+w+'-h'+h+'-c');
}
function thumb(e,w){
  var u='';
  if(e.media$thumbnail){u=e.media$thumbnail.url}
  else{var m=/<img[^>]+src=["']([^"']+)["']/i.exec((e.content&&e.content.$t)||'');if(m)u=m[1]}
  return resize(u,w);
}
function norm(e){
  var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0];
  return {t:e.title.$t,u:l?l.href:'#',d:e.published.$t,c:(e.category&&e.category[0])?e.category[0].term:'',e:e};
}
function get(label,n){
  var u='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results='+n;
  return fetch(u).then(function(r){return r.json()}).then(function(j){return (j.feed.entry||[]).map(norm)}).catch(function(){return[]});
}
function overlay(p){
  var im=thumb(p.e,800);
  return '<article class="ov"><a class="thumb" href="'+p.u+'">'+(im?'<img src="'+im+'" alt="'+esc(p.t)+'" decoding="async">':'')+'</a><div class="cb">'+(p.c?'<span class="tag">'+esc(p.c)+'</span>':'')+'<h3><a href="'+p.u+'">'+esc(p.t)+'</a></h3><time>'+fmt(p.d)+'</time></div></article>';
}
function lead(p,w){
  var im=thumb(p.e,w||640);
  return '<article class="lead"><a class="thumb" href="'+p.u+'">'+(im?'<img loading="lazy" decoding="async" src="'+im+'" alt="'+esc(p.t)+'">':'<span class="noimg"></span>')+'</a><h3><a href="'+p.u+'">'+esc(p.t)+'</a></h3><time>'+fmt(p.d)+'</time></article>';
}
function mini(p){
  var im=thumb(p.e,200);
  return '<article class="mini"><a class="thumb" href="'+p.u+'">'+(im?'<img loading="lazy" decoding="async" src="'+im+'" alt="'+esc(p.t)+'">':'<span class="noimg"></span>')+'</a><div><h3><a href="'+p.u+'">'+esc(p.t)+'</a></h3><time>'+fmt(p.d)+'</time></div></article>';
}

/* Ticker + hero */
get('',Math.max(CFG.tickerCount,CFG.heroCount)).then(function(posts){
  var tk=$('#ticker');
  if(posts.length){tk.innerHTML=posts.slice(0,CFG.tickerCount).map(function(p){return '<a href="'+p.u+'">'+esc(p.t)+'</a>'}).join('')}
  else{$('#ticker-wrap').style.display='none'}
  if(isHome){$('#hero').innerHTML=posts.slice(0,CFG.heroCount).map(overlay).join('')}
});

/* Home: category blocks */
if(isHome){
  var cb=$('#cat-blocks');
  var slots=CFG.sections.map(function(){var d=document.createElement('div');cb.appendChild(d);return d});
  CFG.sections.forEach(function(s,i){
    get(s.label,CFG.perSection).then(function(ps){
      if(!ps.length)return;
      slots[i].innerHTML='<section class="block"><div class="bh"><h2>'+esc(s.title)+'</h2><a href="/search/label/'+encodeURIComponent(s.label)+'">View all &rarr;</a></div><div class="bg">'+lead(ps[0])+'<div class="minis">'+ps.slice(1).map(mini).join('')+'</div></div></section>';
    });
  });
}

/* Article extras */
if(isPost){
  var body=$('#post-body');
  if(body){
    var words=(body.textContent||'').trim().split(/\s+/).length,rt=$('#readtime');
    if(rt)rt.textContent=Math.max(1,Math.round(words/200))+' min read';
    $$('img',body).forEach(function(i){i.setAttribute('loading','lazy')});
    var u=encodeURIComponent(location.href.split('?')[0]),tt=encodeURIComponent(document.title);
    var map={fb:'https://www.facebook.com/sharer/sharer.php?u='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+tt,wa:'https://wa.me/?text='+tt+'%20'+u,tg:'https://t.me/share/url?url='+u+'&text='+tt};
    $$('#share [data-s]').forEach(function(a){a.href=map[a.getAttribute('data-s')]});
    var cp=$('#copy-link');
    if(cp)cp.addEventListener('click',function(){if(navigator.clipboard){navigator.clipboard.writeText(location.href.split('?')[0]).then(function(){cp.textContent='Copied';setTimeout(function(){cp.textContent='Copy link'},1800)})}});
    var rel=$('#related');
    if(rel){get(rel.getAttribute('data-label'),7).then(function(ps){
      ps=ps.filter(function(p){return p.u.split('?')[0]!==location.href.split('?')[0]}).slice(0,3);
      if(ps.length)rel.innerHTML='<h2 class="sec-title">Related News</h2><div class="rel-grid">'+ps.map(function(p){return lead(p,400)}).join('')+'</div>';
    })}
    var bar=$('#progress');
    window.addEventListener('scroll',function(){var h=body.offsetTop+body.offsetHeight-window.innerHeight;bar.style.width=Math.min(100,Math.max(0,window.scrollY/Math.max(h,1)*100))+'%'},{passive:true});
  }
}

/* UI */
$('#today').textContent=new Date().toLocaleDateString(CFG.locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'});
$('#yr').textContent=new Date().getFullYear();
var ma=$('.menu-area');
$('#menu-btn').addEventListener('click',function(){ma.classList.toggle('open')});
var tb=$('#theme-btn'),root=document.documentElement;
function lab(){tb.textContent=root.getAttribute('data-theme')==='dark'?'Light':'Dark'}
lab();
tb.addEventListener('click',function(){var n=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',n);try{localStorage.setItem('khobor-theme',n)}catch(e){}lab()});
var tp=$('#totop');
window.addEventListener('scroll',function(){tp.classList.toggle('show',window.scrollY>500)},{passive:true});
tp.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
})();
